function F({registerIndicator:b,sourceValues:g,nulls:C}){b({id:"oa-coral",name:"Coral Filter (CORAL)",category:"Trends IIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Smoothing Period",default:21,min:1,max:5e3,step:1},{key:"cd",type:"number",label:"Constant D",default:.4,min:0,max:1,step:.01,tooltip:"Weighting of the cascaded stages. Higher values follow price more closely at the cost of smoothness."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"coral",type:"line",title:"CORAL",style:{color:"#ffeb3b",lineWidth:2}}],calc(s,d){const N=Math.max(1,Math.floor(Number(d.period)||21)),f=Number(d.cd),o=Math.min(1,Math.max(0,Number.isFinite(f)?f:.4)),x=g(s,d.source??"close"),e=2/((N-1)/2+1+1),t=1-e,c=o*o,l=c*o,k=3*(c+l),M=-3*(2*c+o+l),w=3*o+1+l+3*c;let u=0,m=0,n=0,i=0,a=0,p=0;const h=new Array(s.length).fill(NaN);for(let r=0;r<s.length;r++){const y=x[r];Number.isFinite(y)&&(u=e*y+t*u,m=e*u+t*m,n=e*m+t*n,i=e*n+t*i,a=e*i+t*a,p=e*a+t*p,h[r]=-l*p+k*a+M*i+w*n)}return{coral:C(h)}}})}export{F as default};
